import {number,percent,escapeHTML as e} from './core.js';
export function bars(entries,{percentages=false,max=null}={}){const top=max??Math.max(...entries.map(r=>r.value||0),1);return `<div class="bar-chart">${entries.map(r=>`<${r.action?'button':'div'} ${r.action?`data-chart-action="${e(r.action)}"`:''} class="bar-row"><span class="bar-label">${e(r.name)}</span><span class="bar-track"><i style="width:${Math.max(0,Math.min(100,(r.value||0)/top*100))}%;background:${r.color||'#337b6a'}"></i></span><strong>${percentages?percent(r.value):number(r.value)}</strong></${r.action?'button':'div'}>`).join('')}</div>`}
export function coverChart(s){return bars([{name:'原模型 · 点数',value:s.point_coverage,color:'#8faaa1'},{name:'规划模型 · 点数',value:s.planning_point_coverage,color:'#247f6b'},{name:'原模型 · 权重',value:s.weight_coverage,color:'#889db7'},{name:'规划模型 · 权重',value:s.planning_weight_coverage,color:'#477fab'}],{percentages:true,max:1})}
export function cards(s){return `<div class="metric-grid">${[['需求点',number(s.demand_points),'模型输入'],['原模型覆盖',percent(s.point_coverage),number(s.baseline_covered)+' 个完整路径'],['规划模型覆盖',percent(s.planning_point_coverage),number(s.planning_covered)+' 个完整路径'],['新增虚拟节点',number(s.virtual_total),'土地待核查 '+number(s.land_review)]].map(([a,b,c])=>`<div class="metric-card"><span>${a}</span><strong>${b}</strong><small>${c}</small></div>`).join('')}</div>`}
export function cityStats(s){return {regions:1,demand_points:s.n_candidates,baseline_covered:s.baseline_covered_points,planning_covered:s.planning_covered_points,point_coverage:s.n_candidates?s.baseline_covered_points/s.n_candidates:null,planning_point_coverage:s.n_candidates?s.planning_covered_points/s.n_candidates:null,weight_coverage:s.baseline_weight_coverage,planning_weight_coverage:s.planning_weight_coverage,total_weight:s.total_demand_weight,baseline_weight:s.baseline_covered_weight,virtual_total:s.virtual_DZ+s.virtual_LD+s.virtual_DC,land_review:s.virtualLand.needs_review||0,nodes:{DZ:s.K_DZ,LD:s.K_LD,DC:s.K_DC},virtual:{DZ:s.virtual_DZ,LD:s.virtual_LD,DC:s.virtual_DC},types:s.types,virtualLand:s.virtualLand,poi:s.poi};}
export function summaryStats(cities){const all={regions:cities.length,demand_points:0,baseline_covered:0,planning_covered:0,total_weight:0,baseline_weight:0,planning_weight:0,virtual_total:0,land_review:0,nodes:{DZ:0,LD:0,DC:0},virtual:{DZ:0,LD:0,DC:0},types:{},virtualLand:{},poi:{}};for(const c of cities){const s=cityStats(c);for(const k of ['demand_points','baseline_covered','planning_covered','total_weight','baseline_weight','virtual_total','land_review'])all[k]+=s[k];all.planning_weight+=c.total_demand_weight*c.planning_weight_coverage;for(const k of ['nodes','virtual','types','virtualLand','poi'])for(const[key,n]of Object.entries(s[k]||{}))all[k][key]=(all[k][key]||0)+n;}all.point_coverage=all.demand_points?all.baseline_covered/all.demand_points:null;all.planning_point_coverage=all.demand_points?all.planning_covered/all.demand_points:null;all.weight_coverage=all.total_weight?all.baseline_weight/all.total_weight:null;all.planning_weight_coverage=all.total_weight?all.planning_weight/all.total_weight:null;return all}
